    {
      "rank": 1,
      "ballot_id": "B010",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction established the principles that make scalable quantum computation physically conceivable and reshaped quantum information physics.",
        "attribution": "Shor and Steane developed landmark codes, while Kitaev's topological approach connected error correction to robust phases of matter; the three contributions are distinct and complementary.",
        "maturity": "The theory has been extensively developed and tested in increasingly capable experiments, though fault-tolerant computing remains an unfinished engineering and physics challenge.",
        "uncertainties": [
          "The award would recognize foundational theory before large-scale fault-tolerant operation is established."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed precision timekeeping and opened a regime where atomic clocks probe fundamental physics as well as serve metrology.",
        "attribution": "Katori's lattice-clock concept and Ye's major experimental advances provide a strong, complementary attribution.",
        "maturity": "The approach has been replicated and steadily improved, with clock performance and applications demonstrated across laboratories.",
        "uncertainties": [
          "The distinction between the foundational invention and subsequent precision advances would need careful framing."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B027",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit quantum electrodynamics made strong light-matter interaction and controlled quantum optics possible in engineered superconducting devices, becoming a foundation for a major research field.",
        "attribution": "Blais supplied key theoretical architecture, while Wallraff and Schoelkopf were central to its experimental realization and development.",
        "maturity": "The platform is now robust, widely reproduced, and capable of increasingly complex quantum control.",
        "uncertainties": [
          "The boundary between this achievement and the already recognized broader physics of superconducting circuits would require especially careful definition."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Gerhard Rempe",
        "H. Jeff Kimble",
        "Mikhail Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Coherent interfaces between matter and light enabled storage, transfer, and networking of quantum states, extending quantum optics from single systems toward networked architectures.",
        "attribution": "The proposed trio represents influential experimental and conceptual work across cavity interfaces, quantum memories, and network protocols.",
        "maturity": "Core interface phenomena have been demonstrated repeatedly, although large-scale, reliable quantum networks remain under development.",
        "uncertainties": [
          "The broad discovery label spans several achievements and may obscure which specific interface results define the prize."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B015",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Ultracold atoms in optical lattices made controlled studies of strongly interacting lattice systems possible and established quantum simulation as an experimental method.",
        "attribution": "Bloch and Greiner led landmark experimental demonstrations, while Zoller provided influential theoretical foundations; the wider credited group reflects substantial contributions beyond three awardees.",
        "maturity": "The platform has produced robust, reproducible results across many laboratories and has steadily expanded its control and measurement capabilities.",
        "uncertainties": [
          "It remains challenging to distinguish simulation of model systems from definitive resolution of broader condensed-matter questions."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Markus Aspelmeyer",
        "Oskar Painter",
        "Tobias J. Kippenberg"
      ],
      "assessment": {
        "nobel_worthiness": "Cavity optomechanics brought mechanical motion into the quantum-control regime and created a versatile field linking quantum optics, precision measurement, and mesoscopic physics.",
        "attribution": "These researchers helped establish complementary experimental platforms and control methods that shaped the field.",
        "maturity": "Cooling and measurement techniques are now well established, while preparation and verification of increasingly nonclassical mechanical states continue to develop.",
        "uncertainties": [
          "The field's broad progress is distributed across many groups, so a sharply defined discovery and attribution would be needed."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B036",
      "proposed_laureates": [
        "Carlton M. Caves",
        "H. Jeff Kimble",
        "Nergis Mavalvala"
      ],
      "assessment": {
        "nobel_worthiness": "Squeezed light enables measurements beyond the standard quantum limit and has become a concrete tool in precision interferometry, including gravitational-wave detection.",
        "attribution": "Caves established key theoretical ideas, Kimble advanced foundational experiments, and Mavalvala helped bring squeezed-light techniques into gravitational-wave observatories.",
        "maturity": "The effect is confirmed and operational in major instruments, with performance gains demonstrated in practice.",
        "uncertainties": [
          "Credit spans theoretical invention, early optical demonstrations, and later instrument integration; the award's scope would need to select among these stages."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B009",
      "proposed_laureates": [
        "Maciej Lewenstein",
        "Paul B. Corkum"
      ],
      "assessment": {
        "nobel_worthiness": "Electron recollision provided a physical basis for strong-field harmonic generation and attosecond science, allowing ultrafast electron dynamics to be probed and controlled.",
        "attribution": "Corkum's recollision picture and Lewenstein's theoretical treatment are central contributions to the field's development.",
        "maturity": "The framework is supported by extensive experiments and has enabled mature attosecond methods.",
        "uncertainties": [
          "The achievement overlaps with the broader development and recognition of attosecond pulse generation, requiring a precise account of what this specific contribution adds."
        ]
      }
    }
  ]
